$active_menu='digital_assets';include 'header.php';require_once __DIR__.'/../foundation.php';$id=(int)($_GET['id']??0);oecrm_require_permission($conn,'subscriptions',$id?'edit':'create');$companyId=oecrm_current_company_id($conn);$r=['id'=>0,'asset_type'=>'domain','name'=>'','provider'=>'','login_url'=>'','username'=>'','recovery_email'=>'','start_date'=>'','renewal_date'=>'','billing_cycle'=>'yearly','cost'=>0,'currency_code'=>'INR','status'=>'active','notes'=>''];if($id){$r=mysqli_fetch_assoc(mysqli_query($conn,'SELECT * FROM digital_subscriptions WHERE id='.$id.' AND company_id='.$companyId));if(!$r)exit('Subscription not found.');}?><div id="page-wrapper" class="compact-admin-page resource-form-page"><div class="foundation-titlebar"><a href="subscriptions.php"><i class="fa fa-arrow-left"></i> Subscriptions</a><h2><?php echo $id?'Edit':'New';?> Subscription</h2></div><div class="panel panel-default"><div class="panel-body"><form class="resource-form" method="post" action="subscriptionAction.php"><?php echo oecrm_csrf_field();?><input type="hidden" name="id" value="<?php echo $id;?>"><div class="form-group"><label>Type</label><select class="form-control" name="asset_type"><?php foreach(['domain','hosting','ssl','software','ai_tool','cloud','other'] as $v):?><option value="<?php echo $v;?>" <?php echo $r['asset_type']===$v?'selected':'';?>><?php echo ucwords(str_replace('_',' ',$v));?></option><?php endforeach;?></select></div><div class="form-group"><label>Name</label><input class="form-control" name="name" value="<?php echo oecrm_h($r['name']);?>" required></div><div class="form-group"><label>Provider</label><input class="form-control" name="provider" value="<?php echo oecrm_h($r['provider']);?>"></div><div class="form-group"><label>Login URL</label><input class="form-control" type="url" name="login_url" value="<?php echo oecrm_h($r['login_url']);?>"></div><div class="form-group"><label>Username</label><input class="form-control" name="username" value="<?php echo oecrm_h($r['username']);?>"></div><div class="form-group"><label>Password <?php echo $id?'(leave blank to keep)':'';?></label><input class="form-control" type="password" name="secret"></div><div class="form-group"><label>Recovery Email</label><input class="form-control" type="email" name="recovery_email" value="<?php echo oecrm_h($r['recovery_email']);?>"></div><div class="form-group"><label>Renewal Date</label><input class="form-control" type="date" name="renewal_date" value="<?php echo oecrm_h($r['renewal_date']);?>"></div><div class="form-group"><label>Cost</label><input class="form-control" type="number" step=".01" name="cost" value="<?php echo oecrm_h($r['cost']);?>"></div><div class="form-group"><label>Currency</label><input class="form-control" name="currency_code" value="<?php echo oecrm_h($r['currency_code']);?>"></div><div class="form-group resource-notes"><label>Notes</label><textarea class="form-control" name="notes"><?php echo oecrm_h($r['notes']);?></textarea></div><div class="resource-actions"><button class="btn btn-primary"><i class="fa fa-save"></i> Save</button></div></form></div></div></div><?php include 'footer.php';?>
